t.script:
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());

gtag('config', 'G-Y6JMM9VCW2');

/* services.html interactions (sv-): service-area tabs + hash deep links, package switch (narrow screens), FAQ accordion, reveal, pointer effects */
(function () {
  var root = document.querySelector('.sv-root');
  if (!root) return;
  root.classList.add('sv-js');
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var fine = window.matchMedia('(hover: hover) and (pointer: fine)').matches;

  function scrollToEl(el) {
    if (!el) return;
    requestAnimationFrame(function () { el.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'start' }); });
  }
  function setHash(id) {
    try { history.replaceState(null, '', '#' + id); } catch (e) {}
  }
  function keyNav(tabs, e, activate) {
    var i = tabs.indexOf(e.currentTarget), n = tabs.length, j = -1;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (i + 1) % n;
    else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (i - 1 + n) % n;
    else if (e.key === 'Home') j = 0;
    else if (e.key === 'End') j = n - 1;
    if (j < 0) return;
    e.preventDefault(); activate(j, true); tabs[j].focus();
  }

  /* ---------- service-area switcher ---------- */
  var svTabs = [].slice.call(root.querySelectorAll('.sv-tab'));
  var svPanels = svTabs.map(function (t) { return document.getElementById(t.getAttribute('aria-controls')); });
  var ind = root.querySelector('.sv-ind');
  var svCur = 0;
  function moveInd() {
    var t = svTabs[svCur]; if (!ind || !t) return;
    ind.style.width = t.offsetWidth + 'px';
    ind.style.transform = 'translateX(' + t.offsetLeft + 'px)';
  }
  function showSv(i, animate) {
    svCur = i;
    svTabs.forEach(function (t, k) {
      var on = k === i;
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
      var p = svPanels[k];
      p.hidden = !on;
      p.classList.remove('sv-enter');
      if (on && animate && !reduce) { void p.offsetWidth; p.classList.add('sv-enter'); }
    });
    moveInd();
  }
  svPanels.forEach(function (p, k) {
    p.setAttribute('role', 'tabpanel');
    p.setAttribute('aria-labelledby', svTabs[k].id);
    p.tabIndex = 0;
    p.addEventListener('animationend', function (e) { if (e.target === p.querySelector('.et_pb_button')) p.classList.remove('sv-enter'); });
  });
  svTabs.forEach(function (t, k) {
    t.addEventListener('click', function () { if (svCur !== k) showSv(k, true); setHash(svPanels[k].id); });
    t.addEventListener('keydown', function (e) { keyNav(svTabs, e, function (j) { showSv(j, true); setHash(svPanels[j].id); }); });
  });
  showSv(0, false);
  window.addEventListener('resize', moveInd);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(moveInd);

  /* ---------- packages: switch on narrow screens, side by side on wide ---------- */
  var pkSwitch = root.querySelector('.sv-pkg-switch');
  var pkTabs = [].slice.call(root.querySelectorAll('.sv-pkg-tab'));
  var pkCards = pkTabs.map(function (t) { return document.getElementById(t.getAttribute('aria-controls')); });
  var narrow = window.matchMedia('(max-width: 899px)');
  var pkCur = 0;
  function showPk(i, animate) {
    pkCur = i;
    if (pkSwitch) pkSwitch.setAttribute('data-sv-at', String(i));
    pkTabs.forEach(function (t, k) {
      var on = k === i;
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
      var c = pkCards[k];
      if (narrow.matches) {
        c.setAttribute('role', 'tabpanel'); c.setAttribute('aria-labelledby', t.id);
        c.hidden = !on;
        c.classList.remove('sv-enter');
        if (on && animate && !reduce) { void c.offsetWidth; c.classList.add('sv-enter'); }
      } else {
        c.removeAttribute('role'); c.removeAttribute('aria-labelledby'); c.hidden = false;
      }
    });
  }
  pkTabs.forEach(function (t, k) {
    t.addEventListener('click', function () { if (pkCur !== k) showPk(k, true); });
    t.addEventListener('keydown', function (e) { keyNav(pkTabs, e, function (j) { showPk(j, true); }); });
  });
  pkCards.forEach(function (c) { c.addEventListener('animationend', function () { c.classList.remove('sv-enter'); }); });
  showPk(0, false);
  if (narrow.addEventListener) narrow.addEventListener('change', function () { showPk(pkCur, false); });
  else if (narrow.addListener) narrow.addListener(function () { showPk(pkCur, false); });

  /* ---------- hash deep links: #org #resilience #individual #corporate-coaching #new-leader ---------- */
  function openHash(scroll) {
    var id = decodeURIComponent((location.hash || '').slice(1));
    if (!id) return false;
    var si = svPanels.map(function (p) { return p.id; }).indexOf(id);
    if (si > -1) { showSv(si, false); if (scroll) scrollToEl(svPanels[si].closest('.sv-svc')); return true; }
    var pi = pkCards.map(function (c) { return c.id; }).indexOf(id);
    if (pi > -1) { showPk(pi, false); if (scroll) scrollToEl(narrow.matches ? pkSwitch : pkCards[pi]); return true; }
    return false;
  }
  if (openHash(false)) {
    // wait for layout (fonts, images above) before scrolling to the switcher
    window.addEventListener('load', function () { openHash(true); });
    setTimeout(function () { openHash(true); }, 60);
  }
  window.addEventListener('hashchange', function () { openHash(true); });
  // same-hash clicks do not fire hashchange: handle in-page links to these targets directly
  document.addEventListener('click', function (e) {
    var a = e.target.closest && e.target.closest('a[href^="#"], a[href^="services#"]');
    if (!a || e.defaultPrevented || e.metaKey || e.ctrlKey || e.shiftKey) return;
    var id = a.getAttribute('href').split('#')[1];
    var isSv = svPanels.some(function (p) { return p.id === id; }), isPk = pkCards.some(function (c) { return c.id === id; });
    if (!isSv && !isPk) return;
    e.preventDefault();
    try { history.pushState(null, '', '#' + id); } catch (err) {}
    openHash(true);
  });

  /* preload the images of hidden panels once the page has settled */
  window.addEventListener('load', function () {
    setTimeout(function () { root.querySelectorAll('.sv-fig img, .sv-card-fig img').forEach(function (im) { im.loading = 'eager'; }); }, 1200);
  });

  /* ---------- FAQ accordion (first open, others closed; each toggles independently) ---------- */
  var accBtns = [].slice.call(root.querySelectorAll('.sv-acc-btn'));
  function setAcc(b, open) {
    b.setAttribute('aria-expanded', open ? 'true' : 'false');
    var p = document.getElementById(b.getAttribute('aria-controls'));
    if (p) p.classList.toggle('sv-shut', !open);
  }
  accBtns.forEach(function (b, k) {
    setAcc(b, k === 0);
    b.addEventListener('click', function () { setAcc(b, b.getAttribute('aria-expanded') !== 'true'); });
    b.addEventListener('keydown', function (e) {
      var i = accBtns.indexOf(b), j = -1;
      if (e.key === 'ArrowDown') j = Math.min(i + 1, accBtns.length - 1);
      else if (e.key === 'ArrowUp') j = Math.max(i - 1, 0);
      else if (e.key === 'Home') j = 0;
      else if (e.key === 'End') j = accBtns.length - 1;
      if (j > -1) { e.preventDefault(); accBtns[j].focus(); }
    });
  });
  window.addEventListener('beforeprint', function () { accBtns.forEach(function (b) { setAcc(b, true); }); });

  /* ---------- reveal on scroll ---------- */
  var rv = [].slice.call(root.querySelectorAll('.sv-rv'));
  function revealAll() { rv.forEach(function (el) { el.classList.add('sv-in'); }); }
  if (reduce || !('IntersectionObserver' in window)) { revealAll(); }
  else {
    var fired = false;
    var io = new IntersectionObserver(function (entries) {
      fired = true;
      entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('sv-in'); io.unobserve(en.target); } });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    rv.forEach(function (el) { io.observe(el); });
    // safety net: never leave content stuck invisible
    setTimeout(function () {
      if (!fired) { revealAll(); return; }
      rv.forEach(function (el) { if (el.getBoundingClientRect().top < window.innerHeight) el.classList.add('sv-in'); });
    }, 1500);
    window.addEventListener('beforeprint', revealAll);
  }

  /* ---------- pointer effects (fine pointers only) ---------- */
  if (fine && !reduce) {
    root.querySelectorAll('.sv-fig').forEach(function (f) {
      f.addEventListener('pointermove', function (e) {
        var r = f.getBoundingClientRect();
        f.style.setProperty('--sv-px', (((e.clientX - r.left) / r.width - .5) * -10).toFixed(1) + 'px');
        f.style.setProperty('--sv-py', (((e.clientY - r.top) / r.height - .5) * -7).toFixed(1) + 'px');
      });
      f.addEventListener('pointerleave', function () { f.style.setProperty('--sv-px', '0px'); f.style.setProperty('--sv-py', '0px'); });
    });
    root.querySelectorAll('.sv-card, .sv-cta-in').forEach(function (c) {
      c.addEventListener('pointermove', function (e) {
        var r = c.getBoundingClientRect();
        c.style.setProperty('--sv-x', (e.clientX - r.left) + 'px');
        c.style.setProperty('--sv-y', (e.clientY - r.top) + 'px');
      });
    });
  }

  if (window.bhdInitButtons) window.bhdInitButtons();
})();
